/* Emberwild: a dependency-free canvas survival platformer. */
(() => {
'use strict';
const $=id=>document.getElementById(id), canvas=$('world'), ctx=canvas.getContext('2d');
const W=4800, GROUND=540, CAMP=470, DAY=90, NIGHT=45, SAVE='emberwild-v1';
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const rand=(a,b)=>a+Math.random()*(b-a);
const near=(a,b,r)=>Math.abs(a-b)<r;
let viewW=1180,viewH=520,scale=1,camera=0,anim=0,last=0,saveTime=0,spawnTime=5;
let playing=false,paused=false,ended=false,dialogPause=false,sound=false,audio;
let state,particles=[],floaters=[],enemies=[],toastTime=0,restartArmed=false;
let keys={left:false,right:false,jump:false,action:false},jumpBuffer=0,coyote=0;
const terrain=[{x:0,y:540,w:1250,h:600},{x:1390,y:540,w:990,h:600},{x:2530,y:540,w:920,h:600},{x:3610,y:540,w:1190,h:600},
{x:740,y:435,w:170,h:26},{x:1010,y:355,w:170,h:26},{x:1290,y:285,w:170,h:26},{x:1550,y:405,w:190,h:26},{x:1820,y:315,w:180,h:26},{x:2110,y:405,w:180,h:26},{x:2380,y:300,w:170,h:26},{x:2660,y:410,w:180,h:26},{x:2940,y:325,w:190,h:26},{x:3250,y:410,w:170,h:26},{x:3490,y:305,w:170,h:26},{x:3780,y:415,w:180,h:26},{x:4050,y:320,w:200,h:26},{x:4390,y:410,w:200,h:26}];
const resources=[];
function addResource(type,x,y=GROUND){resources.push({id:resources.length,type,x,y,uses:type==='wood'?3:type==='stone'?3:1,left:type==='wood'?3:type==='stone'?3:1,flash:0});}
[190,690,930,1130,1490,1690,1970,2260,2650,2810,3120,3350,3740,3970,4300,4640].forEach(x=>addResource('wood',x));
[310,820,1080,1560,2040,2200,2740,3000,3300,3850,4190,4510].forEach(x=>addResource('stone',x));
[590,990,1770,2170,2880,3220,4090,4420].forEach(x=>addResource('berry',x));
terrain.slice(4).forEach((p,i)=>{if(i%2===1||i===0)addResource('crystal',p.x+p.w/2,p.y);});
function fresh(){return {v:1,player:{x:410,y:480,vx:0,vy:0,dir:1,hp:100,jumps:0,inv:0,cool:0,swing:0},bag:{wood:0,stone:0,crystal:0,berry:3},day:1,time:0,night:false,nights:0,fuel:70,shelter:false,axe:false,beacon:false,kills:0,resources:[],bridges:[]};}
function save(){if(!playing||ended)return;try{state.resources=resources.map(r=>r.left);localStorage.setItem(SAVE,JSON.stringify(state));$('saved').textContent='Adventure saved';}catch{$('saved').textContent='Saving unavailable';}}
function readSave(){try{const s=JSON.parse(localStorage.getItem(SAVE));if(s&&s.v===1&&s.player&&s.bag&&Array.isArray(s.resources)&&Array.isArray(s.bridges)&&Number.isFinite(s.player.x)&&s.day>=1&&s.day<=3&&s.player.hp>0)return s;}catch{}return null;}
function init(s){state=s||fresh();resources.forEach((r,i)=>{r.left=s?(s.resources[i]??r.uses):r.uses;r.flash=0;});particles=[];floaters=[];enemies=[];spawnTime=3;state.player.vx=0;state.player.vy=0;state.player.inv=2;camera=clamp(state.player.x-viewW*.38,0,W-viewW);playing=true;paused=false;ended=false;keys={};$('intro').hidden=true;$('endOverlay').hidden=true;$('pauseOverlay').hidden=true;updateUI();notify(s?'Welcome back to the wild.':'Gather wood and stone. Build before nightfall.');save();}
function notify(msg){$('toast').textContent=msg;toastTime=3;$('toast').classList.add('show');}
function beep(freq=200,dur=.06,type='sine',vol=.025){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(30,freq*.5),audio.currentTime+dur);g.gain.setValueAtTime(vol,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur);}catch{}}
function puff(x,y,color,n=8){for(let i=0;i<n;i++)particles.push({x,y,vx:rand(-65,65),vy:rand(-110,-20),life:rand(.3,.7),color,size:rand(2,5)});}
function floater(x,y,text,color='#ffe1a2'){floaters.push({x,y,text,color,life:1.2});}
function allTerrain(){return terrain.concat(state.bridges.map(x=>({x,y:540,w:160,h:16,bridge:true})));}
function moveBody(b,dt,w,h){const oldY=b.y;b.vy+=1150*dt;b.x=clamp(b.x+b.vx*dt,12,W-w-12);b.y+=b.vy*dt;let grounded=false;for(const p of allTerrain()){if(b.vy>=0&&oldY+h<=p.y+3&&b.y+h>=p.y&&b.x+w>p.x&&b.x<p.x+p.w){b.y=p.y-h;b.vy=0;grounded=true;}}return grounded;}
function getNearby(){const p=state.player;return resources.filter(r=>r.left>0&&Math.abs(r.x-(p.x+13))<77&&Math.abs(r.y-(p.y+40))<65).sort((a,b)=>Math.abs(a.x-p.x)-Math.abs(b.x-p.x))[0];}
function doAction(){if(!playing||paused||ended)return;const p=state.player;if(p.cool>0)return;p.cool=.34;p.swing=.22;beep(210,.06,'triangle');let hit=false;for(const e of enemies){if(Math.abs(e.x-p.x)<92&&Math.abs(e.y-p.y)<65){e.hp-=state.axe?42:24;e.vx=p.dir*200;e.x=clamp(e.x+p.dir*24,0,W-30);puff(e.x+15,e.y+15,'#a3c2b6',7);hit=true;if(e.hp<=0){state.kills++;floater(e.x,e.y,'+1 berry');state.bag.berry++;beep(380,.13);}}}enemies=enemies.filter(e=>e.hp>0);if(hit)return;const r=getNearby();if(!r)return;r.left--;r.flash=.22;const n=r.type==='wood'?3:r.type==='stone'?2:r.type==='berry'?3:1;state.bag[r.type]+=n;p.dir=r.x<p.x?-1:1;puff(r.x,r.y-30,r.type==='crystal'?'#a3e4cf':r.type==='berry'?'#ce8c8d':'#c4b98b');floater(r.x,r.y-60,`+${n} ${r.type}`);beep(r.type==='crystal'?720:310,.09);updateUI();}
function jump(){if(!playing||paused||ended)return;jumpBuffer=.14;}
function eat(){if(!playing||paused||ended)return;if(state.bag.berry<1){notify('Find berry bushes or defeat shadows for food.');return;}if(state.player.hp>=100){notify('Health is already full. Save those berries.');return;}state.bag.berry--;state.player.hp=Math.min(100,state.player.hp+25);floater(state.player.x,state.player.y-10,'+25 health','#b5dda1');beep(520,.14);updateUI();save();}
function hurt(amount){const p=state.player;if(p.inv>0)return;p.hp=Math.max(0,p.hp-amount);p.inv=1.2;puff(p.x+12,p.y+20,'#d9987e',9);beep(95,.2,'sawtooth',.025);if(p.hp<=0)finish(false);}
function finish(won){ended=true;paused=true;try{localStorage.removeItem(SAVE);}catch{}$('endLabel').textContent=won?'THREE NIGHTS. ONE NEW HOME.':'THE FOREST KEEPS ITS SECRETS';$('endTitle').textContent=won?'You belong here.':'A spark is never the end.';$('endCopy').textContent=won?`You survived three nights, defeated ${state.kills} shadows, and made a little home in the wild. The next adventure is yours.`:`You made it to ${state.night?'night':'day'} ${state.day}. Gather early, build a shelter, and stay near your fire after dark.`;$('again').textContent=won?'Explore all over again →':'Try another adventure →';$('endOverlay').hidden=false;}
function togglePause(force){if(!playing||ended||!$('buildOverlay').hidden)return;paused=typeof force==='boolean'?force:!paused;$('pauseOverlay').hidden=!paused;$('pause').textContent=paused?'▶':'Ⅱ';keys={};if(paused)save();}
const recipes=[{id:'fuel',name:'Feed the fire',desc:'+40 fuel · keeps the shadows back',cost:{wood:2}},{id:'shelter',name:'Forest shelter',desc:'Heal near camp · take half damage there',cost:{wood:8,stone:4}},{id:'axe',name:'Sharpened axe',desc:'Deal much more damage to shadows',cost:{wood:4,stone:4}},{id:'beacon',name:'Crystal beacon',desc:'A wider, stronger circle of firelight',cost:{wood:6,stone:6,crystal:3}}];
function canAfford(cost){return Object.entries(cost).every(([k,v])=>state.bag[k]>=v);}
function renderRecipes(){const root=$('recipes');root.replaceChildren();for(const r of recipes){const built=r.id!=='fuel'&&state[r.id];const row=document.createElement('div');row.className='recipe';const info=document.createElement('div');const name=document.createElement('strong');name.textContent=r.name;const desc=document.createElement('small');desc.textContent=r.desc;const cost=document.createElement('small');cost.textContent=Object.entries(r.cost).map(([k,v])=>`${v} ${k}`).join(' · ');info.append(name,desc,cost);const btn=document.createElement('button');btn.textContent=built?'Built ✓':r.id==='fuel'?'Refuel +40':'Build';btn.disabled=built||!canAfford(r.cost)||(r.id==='fuel'&&state.fuel>=100);btn.onclick=()=>craft(r.id);row.append(info,btn);root.append(row);}}
function openBuild(){if(!playing||ended)return;if(Math.abs(state.player.x-CAMP)>200||state.player.y<400){notify('Return to the campfire to build. Follow the camp marker.');return;}paused=true;keys={};$('buildOverlay').hidden=false;renderRecipes();}
function craft(id){const r=recipes.find(r=>r.id===id);if(!r||!canAfford(r.cost)||(id!=='fuel'&&state[id]))return;for(const [k,v]of Object.entries(r.cost))state.bag[k]-=v;if(id==='fuel')state.fuel=Math.min(100,state.fuel+40);else state[id]=true;beep(570,.2,'triangle');$('campHint').textContent=id==='fuel'?'The fire burns a little brighter.':`${r.name} built. A good day’s work.`;updateUI();renderRecipes();save();}
function closeBuild(){$('buildOverlay').hidden=true;paused=false;keys={};}
function bridge(){if(!playing||paused||ended)return;const p=state.player;const gap=[1250,2380,3450].find(x=>Math.abs(p.x-x)<150&&!state.bridges.includes(x));if(gap===undefined){notify('Stand near a ravine to build a bridge.');return;}if(state.bag.wood<3){notify('A bridge needs 3 wood. You can also double-jump the gap.');return;}state.bag.wood-=3;state.bridges.push(gap);puff(gap,540,'#b49b68',15);notify('Bridge built. A safer way home.');updateUI();save();}
function updateUI(){if(!state)return;const p=state.player;$('hpText').textContent=Math.ceil(p.hp);$('hpBar').style.width=`${p.hp}%`;$('fuelText').textContent=Math.ceil(state.fuel);$('fuelBar').style.width=`${state.fuel}%`;for(const k of ['wood','stone','crystal','berry'])$(k).textContent=state.bag[k];$('phase').textContent=`${state.night?'NIGHT':'DAY'} 0${state.day}`;$('clock').textContent=`${state.night?'Dawn in':'Daylight ·'} ${Math.ceil((state.night?NIGHT:DAY)-state.time)}s`;$('nights').textContent=Array.from({length:3},(_,i)=>i<state.nights?'●':'○').join(' ');$('region').textContent=p.x<1250?'THE HOLLOW':p.x<2380?'MOSSWOOD RIDGE':p.x<3450?'THE CRYSTAL REACH':'THE FAR PINES';$('objective').textContent=state.night?'Keep the fire alive':'Survive three nights';$('eat').disabled=state.bag.berry<1||p.hp>=100;const off=CAMP<camera||CAMP>camera+viewW;$('campMarker').hidden=!off||!playing;$('campMarker').textContent=CAMP<camera?'← Camp':'Camp →';$('campMarker').style.left=CAMP<camera?'12px':'auto';$('campMarker').style.right=CAMP<camera?'auto':'12px';}
function update(dt){if(!playing||paused||ended)return;const p=state.player;state.time+=dt;if(state.time>=(state.night?NIGHT:DAY)){state.time=0;state.night=!state.night;if(!state.night){state.nights++;if(state.nights>=3){finish(true);return;}state.day++;enemies=[];resources.forEach(r=>r.left=r.uses);notify(`Day ${state.day}. Supplies have regrown. A new chance to explore.`);state.player.hp=Math.min(100,p.hp+15);}else{spawnTime=1.5;notify('Nightfall. Return to your fire. Shadows are waking.');beep(130,.5,'triangle');}save();}
state.fuel=Math.max(0,state.fuel-dt*(state.night?.8:.025));
const dir=(keys.right?1:0)-(keys.left?1:0);p.vx=dir*230;if(dir)p.dir=dir;p.cool=Math.max(0,p.cool-dt);p.swing=Math.max(0,p.swing-dt);p.inv=Math.max(0,p.inv-dt);jumpBuffer=Math.max(0,jumpBuffer-dt);coyote=Math.max(0,coyote-dt);
if(jumpBuffer>0&&(p.jumps<2||coyote>0)){if(coyote>0)p.jumps=0;p.vy=p.jumps===0?-465:-430;p.jumps++;jumpBuffer=0;coyote=0;beep(p.jumps===1?320:450,.08,'triangle');puff(p.x+12,p.y+42,'#afbb8c',5);}
const grounded=moveBody(p,dt,26,44);if(grounded){p.jumps=0;coyote=.1;}else if(p.jumps===0&&coyote<=0)p.jumps=1;
if(p.y>840){p.inv=0;hurt(20);p.x=CAMP+35;p.y=470;p.vy=0;p.jumps=0;notify('A rough landing. Back to camp (−20 health).');}
if(state.shelter&&near(p.x,CAMP,140)&&state.fuel>0&&p.y>450)p.hp=Math.min(100,p.hp+dt*1.8);
if(keys.action)doAction();
if(state.night){spawnTime-=dt;if(spawnTime<=0&&enemies.length<9){spawnTime=rand(4.5,7.5)/Math.sqrt(state.day);const x=clamp(p.x+(Math.random()<.5?-1:1)*rand(430,650),30,W-50);enemies.push({x,y:300,vx:0,vy:0,hp:state.day===3?80:55,attack:0,seed:Math.random()*10});}}
for(const e of enemies){e.attack=Math.max(0,e.attack-dt);const dist=p.x-e.x;e.vx=Math.sign(dist)*(state.day*12+54);const groundedE=moveBody(e,dt,30,31);if(groundedE&&p.y+44<e.y-20&&Math.abs(dist)<280)e.vy=-410;const fireRadius=state.beacon?245:125;if(state.fuel>0&&near(e.x,CAMP,fireRadius)&&e.y>400){e.hp-=dt*(state.beacon?32:17);if(Math.random()<dt*5)puff(e.x,e.y,'#e8bd7e',2);}if(Math.abs(e.x-p.x)<29&&Math.abs(e.y-p.y)<38&&e.attack<=0){hurt(state.shelter&&near(p.x,CAMP,150)?6:12);e.attack=1.2;}if(e.y>880)e.hp=0;}
enemies=enemies.filter(e=>e.hp>0);for(const r of resources)r.flash=Math.max(0,r.flash-dt);
camera+=(clamp(p.x-viewW*.4,0,Math.max(0,W-viewW))-camera)*Math.min(1,dt*6);
const r=getNearby();const gap=[1250,2380,3450].find(x=>Math.abs(p.x-x)<110&&!state.bridges.includes(x));const contextKey=gap!==undefined?'bridge:'+gap:r?'resource:'+r.id:near(p.x,CAMP,150)&&p.y>400?'camp':'';if($('context').dataset.key!==contextKey){$('context').dataset.key=contextKey;$('context').replaceChildren();if(gap!==undefined){const btn=document.createElement('button');btn.textContent='Bridge · 3 wood [F]';btn.style.cssText='border:0;background:none;color:inherit;font:inherit;pointer-events:auto;padding:2px;';btn.onclick=bridge;$('context').append(btn);}else $('context').textContent=r?`Hold Action / E · ${r.type==='wood'?'gather wood':r.type==='stone'?'mine stone':r.type==='berry'?'pick berries':'collect crystal'}`:near(p.x,CAMP,150)&&p.y>400?'Your camp · Build / B':'';}
saveTime+=dt;if(saveTime>5){saveTime=0;save();}updateUI();}
// Art is drawn locally: layered mountains, wind-shaped pines, mossy platforms and a tiny traveller.
function poly(points,color){ctx.fillStyle=color;ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.fill();}
function ellipse(x,y,rx,ry,color){ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill();}
function pine(x,y,h,c,detail=false){ctx.fillStyle=c;ctx.fillRect(x-3,y-h*.7,6,h*.7);for(let i=0;i<4;i++){const ty=y-h+i*h*.17;const w=h*(.15+i*.035);poly([[x,ty],[x-w,ty+h*.38],[x+w,ty+h*.38]],c);}if(detail){ctx.strokeStyle='#a6b59214';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x,y-h+10);ctx.lineTo(x-2,y-12);ctx.stroke();}}
function background(n){const grad=ctx.createLinearGradient(0,0,0,viewH);grad.addColorStop(0,n?'#152d3a':'#527568');grad.addColorStop(.65,n?'#304941':'#90a68a');grad.addColorStop(1,n?'#3b5145':'#c4c3a0');ctx.fillStyle=grad;ctx.fillRect(0,0,viewW,viewH);
if(n){for(let i=0;i<60;i++){const x=(i*173.7-camera*.04)%(viewW+200);const y=20+(i*91.1)%(viewH*.5);ctx.globalAlpha=.3+(Math.sin(anim*.6+i)+1)*.18;ellipse(x,y,1,1,'#f1e6c2');}ctx.globalAlpha=1;ellipse(viewW*.77,viewH*.17,25,25,'#d6d8b3');ellipse(viewW*.77+11,viewH*.17-6,24,24,'#1b3340');}else{const glow=ctx.createRadialGradient(viewW*.73,viewH*.17,0,viewW*.73,viewH*.17,170);glow.addColorStop(0,'#eddcaa66');glow.addColorStop(1,'#ddd6ac00');ctx.fillStyle=glow;ctx.fillRect(0,0,viewW,viewH);ellipse(viewW*.73,viewH*.17,27,27,'#e5d2a1');}
for(let layer=0;layer<3;layer++){let pts=[[0,viewH]];for(let x=-100;x<=viewW+100;x+=45){const q=x+camera*(.04+layer*.055);const y=viewH*(.47+layer*.12)+Math.sin(q*.003+layer*3)*45+Math.cos(q*.008+layer)*23;pts.push([x,y]);}pts.push([viewW,viewH]);poly(pts,n?['#284846','#2c5148','#335b4a'][layer]:['#6d8d78','#62846e','#4f775e'][layer]);}
for(let i=0;i<36;i++){const x=i*116-camera*.23;const xx=((x%(viewW+300))+(viewW+300))%(viewW+300)-150;const h=100+(i*47)%170;pine(xx,viewH*.95,h,n?'#27483c':'#3d654e');}
ctx.fillStyle=n?'#173e2c33':'#d7d6a51a';ctx.fillRect(0,viewH*.7,viewW,viewH*.3);
for(let i=0;i<10;i++){const x=((i*191+anim*6-camera*.1)%(viewW+160))-80;const y=80+(i*47)%(viewH-80)+Math.sin(anim*.5+i)*12;ellipse(x,y,2,1,'#e4d6aa35');}}
function drawTerrain(p){const x=p.x-camera,y=p.y;if(x+p.w<0||x>viewW)return;if(p.bridge){ctx.fillStyle='#917d54';ctx.fillRect(x,y,p.w,13);ctx.fillStyle='#4c4d35';for(let i=0;i<p.w;i+=16)ctx.fillRect(x+i,y,2,13);return;}const ground=p.h>100;ctx.fillStyle=ground?'#344136':'#495341';ctx.fillRect(x,y,p.w,p.h);ctx.fillStyle='#738568';ctx.fillRect(x,y,p.w,8);ctx.fillStyle='#a4af7c';ctx.fillRect(x,y,p.w,3);ctx.fillStyle='#28392f';ctx.fillRect(x,y+12,p.w,ground?9:5);if(!ground){poly([[x,y+25],[x+p.w*.15,y+50],[x+p.w*.36,y+39],[x+p.w*.65,y+61],[x+p.w,y+25]],'#354536');for(let i=0;i<3;i++){ctx.strokeStyle='#81946c';ctx.beginPath();ctx.moveTo(x+30+i*47,y+30);ctx.quadraticCurveTo(x+15+i*48,y+58,x+35+i*47,y+66);ctx.stroke();}}for(let i=0;i<p.w;i+=17){const h=4+((i*13)%9);ctx.strokeStyle=i%3?'#8f9e70':'#b5b989';ctx.beginPath();ctx.moveTo(x+i,y);ctx.lineTo(x+i-3,y-h);ctx.moveTo(x+i,y);ctx.lineTo(x+i+2,y-h-2);ctx.stroke();}if(ground){ctx.fillStyle='#89947717';for(let i=0;i<p.w;i+=39)ctx.fillRect(x+i+9,y+35+(i%29),12,3);}}
function treeResource(r){const x=r.x-camera,y=r.y;const h=120+(r.id*23)%65;if(r.left<=0){ctx.fillStyle='#706043';ctx.fillRect(x-9,y-13,18,13);ellipse(x,y-13,9,3,'#a59468');return;}ctx.save();ctx.translate(x+(r.flash>0?Math.sin(anim*80)*3:0),y);ctx.fillStyle='#716544';ctx.fillRect(-7,-h*.58,14,h*.58);ctx.fillStyle='#9b8a5d';ctx.fillRect(-7,-h*.58,3,h*.58);for(let i=0;i<4;i++){const top=-h+i*h*.17;const width=h*(.19+i*.04);poly([[0,top],[-width,top+h*.37],[-width*.6,top+h*.35],[width,top+h*.37]],['#274c35','#315b3e','#3e6744','#557a4e'][i]);}ctx.restore();}
function drawResource(r){const x=r.x-camera,y=r.y;if(x<-150||x>viewW+150)return;if(r.type==='wood'){treeResource(r);return;}if(r.left<=0)return;if(r.type==='stone'){poly([[x-24,y],[x-29,y-13],[x-14,y-33],[x+10,y-35],[x+29,y-10],[x+22,y]],r.flash?'#c2c9ae':'#8b9c8b');poly([[x-14,y-33],[x+10,y-35],[x+1,y-13],[x-29,y-13]],'#a7b4a0');poly([[x+1,y-13],[x+10,y-35],[x+29,y-10],[x+22,y]],'#728c7c');}else if(r.type==='berry'){ellipse(x,y-13,29,16,'#375a36');ellipse(x-13,y-22,17,15,'#466b3e');ellipse(x+12,y-23,18,14,'#507642');for(let i=0;i<6;i++)ellipse(x-19+(i*13)%39,y-10-(i*7)%23,3.5,3.5,'#c58a7b');}else{const b=Math.sin(anim*2+r.id)*3;const glow=ctx.createRadialGradient(x,y-19,2,x,y-19,50);glow.addColorStop(0,'#a1edc93a');glow.addColorStop(1,'#a1edc900');ctx.fillStyle=glow;ctx.fillRect(x-50,y-69,100,100);poly([[x,y-39+b],[x-11,y-21+b],[x,y-3+b],[x+11,y-21+b]],'#aed5b6');poly([[x,y-39+b],[x,y-3+b],[x+11,y-21+b]],'#6fac99');ctx.fillStyle='#e2edd0';ctx.fillRect(x-2,y-30+b,2,8);}}
function drawCamp(){const x=CAMP-camera,y=GROUND;if(state.shelter){poly([[x-105,y],[x-66,y-81],[x-27,y]],'#bca878');poly([[x-66,y-81],[x-27,y],[x-5,y]],'#8d885d');poly([[x-75,y],[x-65,y-52],[x-50,y]],'#354936');ctx.strokeStyle='#e4d4a2';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x-108,y);ctx.lineTo(x-65,y-84);ctx.lineTo(x-23,y);ctx.stroke();}else{ctx.strokeStyle='#8f9c73';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x-100,y);ctx.lineTo(x-80,y-34);ctx.lineTo(x-60,y);ctx.stroke();ctx.setLineDash([3,4]);ctx.strokeStyle='#9aa77c66';ctx.strokeRect(x-110,y-65,60,65);ctx.setLineDash([]);}
if(state.beacon){ctx.fillStyle='#768d73';ctx.fillRect(x+65,y-95,10,95);poly([[x+70,y-123],[x+57,y-104],[x+70,y-84],[x+83,y-104]],'#adedd1');}
if(state.fuel>0){const radius=state.beacon?245:155;const glow=ctx.createRadialGradient(x,y-20,5,x,y-20,radius);glow.addColorStop(0,'#e9b97533');glow.addColorStop(1,'#e9b97500');ctx.fillStyle=glow;ctx.fillRect(x-radius,y-radius-20,radius*2,radius*2);for(let i=0;i<4;i++){const f=Math.sin(anim*8+i*3)*5;poly([[x-13+i*5,y-9],[x-7+i*4,y-48+f+i*4],[x+8+i*3,y-9]],['#b77541','#e39c4e','#e9c579','#f0d89b'][i]);}for(let i=0;i<6;i++){const t=(anim*.7+i*.17)%1;ellipse(x+Math.sin(i*6+anim)*t*20,y-20-t*70,1.5*(1-t),2*(1-t),'#f3d08b');}}
ctx.strokeStyle='#785d40';ctx.lineWidth=6;ctx.beginPath();ctx.moveTo(x-19,y-2);ctx.lineTo(x+17,y-12);ctx.moveTo(x-18,y-13);ctx.lineTo(x+20,y-2);ctx.stroke();for(let i=0;i<6;i++)ellipse(x-26+i*10,y+2+Math.sin(i)*2,5,3,'#8d9580');ctx.font='8px Arial';ctx.textAlign='center';ctx.fillStyle='#d4d3a6';ctx.fillText('C A M P',x,y+25);}
function drawPlayer(p){const x=p.x-camera,y=p.y;ctx.save();ctx.translate(x+13,y+23);if(p.inv>0&&Math.floor(anim*14)%2===0)ctx.globalAlpha=.5;ctx.scale(p.dir,1);const step=Math.abs(p.vx)>0?Math.sin(anim*16)*6:0;ctx.fillStyle='#384c3c';ctx.fillRect(-9,8,7,14+step*.5);ctx.fillRect(2,8,7,14-step*.5);ctx.fillStyle='#b6a47d';ctx.fillRect(-10,18+step*.5,9,4);ctx.fillRect(1,18-step*.5,10,4);poly([[-10,-9],[9,-8],[12,12],[-12,12]],'#b4744b');poly([[-9,-8],[-18,-3-Math.sin(anim*5)*2],[-12,9],[-3,6]],'#d2a66c');ctx.fillStyle='#54624b';ctx.fillRect(-13,-6,7,17);ctx.fillStyle='#e4c79a';ctx.fillRect(-7,-22,15,13);ctx.fillStyle='#554d37';ctx.fillRect(-8,-24,15,6);ctx.fillRect(-10,-22,5,10);ctx.fillStyle='#263a2e';ctx.fillRect(4,-17,2,2);ctx.fillStyle='#ddd0a1';ctx.fillRect(-9,-11,19,5);ctx.save();ctx.translate(8,0);ctx.rotate(p.swing>0?-1.4+p.swing*12:.3);ctx.strokeStyle='#b6a276';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(0,6);ctx.lineTo(0,-17);ctx.stroke();poly([[-1,-17],[11,-20],[14,-11],[0,-9]],state.axe?'#e5e2bd':'#9cae98');ctx.restore();if(p.swing>0){ctx.strokeStyle='#ebd9a36b';ctx.lineWidth=3;ctx.beginPath();ctx.arc(10,-3,34,-1.5,1.2);ctx.stroke();}ctx.restore();}
function drawEnemy(e){const x=e.x-camera,y=e.y;const bob=Math.sin(anim*6+e.seed)*2;ellipse(x+15,y+29,20,4,'#102d2266');poly([[x-2,y+26],[x+3,y+5+bob],[x+15,y-2+bob],[x+29,y+8+bob],[x+33,y+28],[x+23,y+24],[x+15,y+31],[x+6,y+25]],'#203c35');ctx.fillStyle='#ddbc87';ctx.fillRect(x+8,y+11+bob,4,3);ctx.fillRect(x+20,y+11+bob,4,3);}
function draw(dt){anim+=dt;background(state.night);ctx.save();const worldOffset=viewH-GROUND-62+Math.max(0,(GROUND-44)-state.player.y-viewH*.45);ctx.translate(0,worldOffset);for(const p of allTerrain())drawTerrain(p);for(const r of resources)drawResource(r);drawCamp();for(const e of enemies)drawEnemy(e);drawPlayer(state.player);
for(const p of particles){p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=180*dt;ctx.globalAlpha=Math.max(0,p.life*1.5);ctx.fillStyle=p.color;ctx.fillRect(p.x-camera,p.y,p.size,p.size);}ctx.globalAlpha=1;particles=particles.filter(p=>p.life>0);for(const f of floaters){f.life-=dt;f.y-=dt*25;ctx.globalAlpha=clamp(f.life,0,1);ctx.font='11px Arial';ctx.textAlign='center';ctx.fillStyle=f.color;ctx.fillText(f.text,f.x-camera,f.y);}ctx.globalAlpha=1;floaters=floaters.filter(f=>f.life>0);ctx.restore();const vignette=ctx.createLinearGradient(0,0,0,viewH);vignette.addColorStop(0,'#14352a22');vignette.addColorStop(.65,'#12342500');vignette.addColorStop(1,'#11291f88');ctx.fillStyle=vignette;ctx.fillRect(0,0,viewW,viewH);}
function resize(){const rect=canvas.getBoundingClientRect();const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);scale=rect.height<260?.60:rect.width<550?.85:1;viewW=rect.width/scale;viewH=rect.height/scale;ctx.setTransform(dpr*scale,0,0,dpr*scale,0,0);}
function frame(t){const dt=Math.min((t-last)/1000||.016,.04);last=t;if(toastTime>0){toastTime-=dt;if(toastTime<=0)$('toast').classList.remove('show');}update(dt);draw(dt);requestAnimationFrame(frame);}
window.addEventListener('resize',resize);document.addEventListener('fullscreenchange',resize);
const keyMap={a:'left',ArrowLeft:'left',d:'right',ArrowRight:'right',e:'action'};
document.addEventListener('keydown',e=>{if(e.target instanceof HTMLInputElement)return;const k=e.key.length===1?e.key.toLowerCase():e.key;if([' ','ArrowUp','ArrowLeft','ArrowRight','ArrowDown'].includes(k))e.preventDefault();if($('guide').open){if(k==='Escape')$('guide').close();return;}if(keyMap[k])keys[keyMap[k]]=true;if(k==='e')doAction();if(e.repeat)return;if(k===' '||k==='w'||k==='ArrowUp')jump();if(k==='q')eat();if(k==='b'){if(!$('buildOverlay').hidden)closeBuild();else if(!paused)openBuild();}if(k==='f')bridge();if(k==='Escape'||k==='p'){if(!$('buildOverlay').hidden)closeBuild();else togglePause();}});
document.addEventListener('keyup',e=>{const k=e.key.length===1?e.key.toLowerCase():e.key;if(keyMap[k])keys[keyMap[k]]=false;});
const heldPointers=new Map();document.querySelectorAll('[data-hold]').forEach(btn=>{btn.addEventListener('pointerdown',e=>{e.preventDefault();btn.setPointerCapture(e.pointerId);const k=btn.dataset.hold;heldPointers.set(e.pointerId,k);btn.classList.add('active');if(k==='jump')jump();else{keys[k]=true;if(k==='action')doAction();}});const up=e=>{const k=heldPointers.get(e.pointerId);heldPointers.delete(e.pointerId);if(k)keys[k]=[...heldPointers.values()].includes(k);btn.classList.remove('active');};btn.addEventListener('pointerup',up);btn.addEventListener('pointercancel',up);btn.addEventListener('lostpointercapture',up);});
window.addEventListener('blur',()=>{keys={};if(playing&&!ended&&$('buildOverlay').hidden)togglePause(true);});document.addEventListener('visibilitychange',()=>{if(document.hidden){keys={};save();if(playing&&!ended&&$('buildOverlay').hidden)togglePause(true);}});
$('start').onclick=()=>init();const saved=readSave();if(saved){$('continue').hidden=false;$('continue').onclick=()=>init(readSave()||fresh());$('start').textContent='Start a new adventure →';}
$('pause').onclick=()=>togglePause();$('resume').onclick=()=>togglePause(false);$('restart').onclick=()=>{if(!restartArmed){restartArmed=true;$('restartHint').hidden=false;return;}restartArmed=false;$('restartHint').hidden=true;init();};$('again').onclick=()=>init();$('eat').onclick=eat;$('build').onclick=()=>{if(!paused)openBuild();};$('closeBuild').onclick=closeBuild;
$('guideButton').onclick=()=>{dialogPause=paused;if(playing&&!ended&&$('buildOverlay').hidden)togglePause(true);$('guide').showModal();};$('closeGuide').onclick=()=>$('guide').close();$('guide').addEventListener('close',()=>{if(playing&&!ended&&$('buildOverlay').hidden&&!dialogPause)togglePause(false);});
$('sound').onclick=()=>{sound=!sound;$('sound').textContent=sound?'Sound on':'Sound off';$('sound').setAttribute('aria-pressed',String(sound));$('sound').setAttribute('aria-label',sound?'Mute game sound':'Enable game sound');beep(500,.15);};
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('shell').requestFullscreen();resize();}catch{notify('Fullscreen is unavailable in this browser. Try landscape.');}};
window.addEventListener('pagehide',save);
state=fresh();state.player.x=560;state.player.y=GROUND-44;resize();camera=0;updateUI();requestAnimationFrame(frame);
})();
